import React, { useState } from 'react';
import { ref, push } from 'firebase/database';
import { db } from '../firebase';

function AddSeries() {
  const [seriesData, setSeriesData] = useState({
    title: '',
    totalSeasons: '',
    episodesPerSeason: '',
    currentSeason: '1',
    currentEpisode: '1',
    watchingTogether: true,
    status: 'active',
    coverImage: ''
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const seriesRef = ref(db, 'series');
      await push(seriesRef, {
        ...seriesData,
        watchedEpisodes: [],
        createdAt: new Date().toISOString(),
        totalSeasons: parseInt(seriesData.totalSeasons),
        episodesPerSeason: parseInt(seriesData.episodesPerSeason),
        currentSeason: parseInt(seriesData.currentSeason),
        currentEpisode: parseInt(seriesData.currentEpisode)
      });
      alert('Dizi başarıyla eklendi!');
      setSeriesData({
        title: '',
        totalSeasons: '',
        episodesPerSeason: '',
        currentSeason: '1',
        currentEpisode: '1',
        watchingTogether: true,
        status: 'active',
        coverImage: ''
      });
    } catch (error) {
      console.error('Error adding series: ', error);
      alert('Dizi eklenirken bir hata oluştu.');
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSeriesData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-lg shadow-md p-8">
      <h2 className="text-2xl font-bold text-purple-600 mb-6">Yeni Dizi Ekle</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-gray-700 mb-2">Dizi Adı</label>
          <input
            type="text"
            name="title"
            value={seriesData.title}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Kapak Fotoğrafı URL</label>
          <input
            type="url"
            name="coverImage"
            value={seriesData.coverImage}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            placeholder="https://example.com/image.jpg"
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Toplam Sezon Sayısı</label>
          <input
            type="number"
            name="totalSeasons"
            value={seriesData.totalSeasons}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Sezon Başına Bölüm Sayısı</label>
          <input
            type="number"
            name="episodesPerSeason"
            value={seriesData.episodesPerSeason}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Mevcut Sezon</label>
          <input
            type="number"
            name="currentSeason"
            value={seriesData.currentSeason}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Mevcut Bölüm</label>
          <input
            type="number"
            name="currentEpisode"
            value={seriesData.currentEpisode}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div className="flex items-center">
          <input
            type="checkbox"
            name="watchingTogether"
            checked={seriesData.watchingTogether}
            onChange={handleChange}
            className="mr-2"
          />
          <label className="text-gray-700">Birlikte İzliyoruz</label>
        </div>
        <button
          type="submit"
          className="w-full bg-purple-600 text-white py-2 px-4 rounded-lg hover:bg-purple-700 transition duration-200"
        >
          Dizi Ekle
        </button>
      </form>
    </div>
  );
}

export default AddSeries;
